//! Clean-room tokenizer: byte-level BPE (GPT-2 / Llama-3 / Qwen) and SentencePiece-style BPE
//! (Llama-2 / Mistral / Gemma), read from a Hugging Face `tokenizer.json` or from GGUF metadata.
//!
//! Written from the public descriptions of the formats only. Dependencies: `serde_json`.
//!
//! * Added / special tokens are matched in the raw text first (leftmost, longest), then the
//!   remaining text is pre-tokenised and merged. Merging uses a rank-ordered priority queue over a
//!   linked list of symbols, so it is `O(n log n)` even for a single enormous "word".
//! * The pre-tokenizer is a small interpreter (no regex engine). A `pre_tokenizer` node becomes a
//!   program of stages (`Split` regexes in the shapes real models use, `Digits`, `ByteLevel`); the
//!   GPT-2, Llama-3, Qwen-2 and DeepSeek (llm / coder / v3) patterns are recognised and run by
//!   hand-written code over exact Unicode `\p{L}\p{M}\p{N}\p{P}\p{S}` tables (Unicode 15.1).
//!   Anything not recognised is reported through [`Tokenizer::warnings`], never silently dropped.
//! * Normalisers (`NFC`, `NFKC`-lite, `Lowercase`, `Strip`, `Prepend`, string `Replace`, and
//!   `Sequence`s of them) are applied to each text segment; unknown ones produce a warning.
//! * Nothing here panics on hostile input: malformed JSON, absurd ids, truncated GGUF arrays and
//!   invalid UTF-8 produced by decoding are all handled.
//!
//! Verified against llama.cpp's reference outputs (46 cases each) for twelve families: Llama-3,
//! Qwen-2, GPT-2, Llama SPM, DeepSeek llm/coder, Phi-3, Falcon, StarCoder, MPT, Command-R, Refact.
//!
//! Known limits: NFC is exact for canonical compositions but skips CJK compatibility ideographs;
//! NFKC is a subset (full-width forms, spaces, ligatures) and sentencepiece's `Precompiled`
//! charsmap is approximated by it; regex normalisers and regexes outside the recognised shapes are
//! approximated by the closest family (with a warning); WordPiece/Unigram JSON models are
//! rejected; GGUF token arrays longer than 2^20 entries are truncated by the GGUF reader; in
//! SentencePiece mode the dummy-prefix `▁` is added only at the very start of the text. GPT-NeoX,
//! Aquila and Baichuan have no reference outputs here (only load, determinism and round trip).
use crate::gguf::{Gguf, Value as GValue};
use serde_json::Value;
use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

const SPACE: char = '\u{2581}';
/// Longest run of bytes handed to BPE in one go. A longer unbroken piece (base64, minified code, a
/// 4 MiB line without spaces) is cut into windows at character boundaries, so memory per call stays
/// bounded; only inputs with pieces beyond this length can tokenise differently from an unbounded merge.
const MAX_BPE_PIECE: usize = 16 * 1024;
/// The same bound for sentencepiece, whose "piece" is the whole segment; windows end after a space
/// when one is near the limit.
const MAX_SP_SEGMENT: usize = 64 * 1024;

#[derive(Default, Debug)]
struct TrieNode {
    kids: Vec<(u8, u32)>, // sorted by byte
    /// lowest index into `added` of a token ending here
    end: Option<u32>,
}
fn build_trie(added: &[(String, u32)]) -> Vec<TrieNode> {
    let mut t = vec![TrieNode::default()];
    for (k, (s, _)) in added.iter().enumerate() {
        let mut n = 0usize;
        for &b in s.as_bytes() {
            n = match t[n].kids.binary_search_by_key(&b, |&(c, _)| c) {
                Ok(p) => t[n].kids[p].1 as usize,
                Err(p) => {
                    let id = t.len() as u32;
                    t.push(TrieNode::default());
                    t[n].kids.insert(p, (b, id));
                    id as usize
                }
            };
        }
        if t[n].end.is_none() {
            t[n].end = Some(k as u32);
        }
    }
    t
}
/// `s` cut into windows of at most `max` bytes at char boundaries; with `at_space`, a window ends
/// just after the last space in its final quarter when there is one.
fn windows(s: &str, max: usize, at_space: bool) -> Vec<&str> {
    if s.len() <= max {
        return vec![s];
    }
    let (mut out, mut i) = (vec![], 0);
    while i < s.len() {
        let mut e = (i + max).min(s.len());
        if e < s.len() {
            while !s.is_char_boundary(e) {
                e -= 1;
            }
            if at_space {
                let mut lo = i + max * 3 / 4;
                while !s.is_char_boundary(lo) {
                    lo += 1;
                }
                if lo < e
                    && let Some(p) = s[lo..e].rfind(' ')
                {
                    e = lo + p + 1;
                }
            }
        }
        out.push(&s[i..e]);
        i = e;
    }
    out
}
const MAX_ID_HARD: u64 = 1 << 22;

#[derive(Debug, PartialEq, Eq)]
pub enum TokError {
    Json(String),
    Unsupported(String),
    Invalid(String),
}
impl std::fmt::Display for TokError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TokError::Json(s) => write!(f, "tokenizer file is not valid JSON: {s}"),
            TokError::Unsupported(s) => write!(f, "tokenizer type not supported: {s}"),
            TokError::Invalid(s) => write!(f, "tokenizer file is inconsistent: {s}"),
        }
    }
}
impl std::error::Error for TokError {}
fn invalid<T>(s: impl Into<String>) -> Result<T, TokError> {
    Err(TokError::Invalid(s.into()))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    /// Bytes mapped to printable characters (GPT-2 alphabet); lossless for any input.
    ByteLevel,
    /// `▁` marks spaces; characters missing from the vocabulary fall back to `<0xNN>` bytes.
    SentencePiece,
}

/// Which pre-tokenisation pattern to emulate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PreCfg {
    /// Llama-3 style (`[^\r\n\p{L}\p{N}]?\p{L}+`, newline handling) instead of GPT-2 style.
    pub new_style: bool,
    /// Contractions (`'s`, `'T`, …) match case-insensitively.
    pub ci_contractions: bool,
    /// Longest run of digits kept together (GPT-2: unlimited, Llama-3: 3, Qwen-2: 1).
    pub digit_max: usize,
    /// Extra stage run BEFORE the main pattern: every `\p{N}` character becomes its own piece
    /// (StarCoder, Refact, Command-R and relatives).
    pub each_digit: bool,
    /// Extra stage run BEFORE the main pattern: runs of `[\p{P}$+<=>^~|]` are cut out (Falcon).
    pub punct_first: bool,
    /// Extra stage run AFTER the main pattern: `[0-9]{3}` groups are cut out of digit runs (Falcon).
    pub triple_digits: bool,
}
impl PreCfg {
    pub const GPT2: PreCfg = PreCfg {
        new_style: false,
        ci_contractions: false,
        digit_max: usize::MAX,
        each_digit: false,
        punct_first: false,
        triple_digits: false,
    };
    pub const LLAMA3: PreCfg = PreCfg {
        new_style: true,
        ci_contractions: true,
        digit_max: 3,
        ..PreCfg::GPT2
    };
    pub const QWEN2: PreCfg = PreCfg {
        new_style: true,
        ci_contractions: true,
        digit_max: 1,
        ..PreCfg::GPT2
    };
    /// StarCoder / Refact / Command-R: single digits, then the GPT-2 pattern.
    pub const STARCODER: PreCfg = PreCfg {
        each_digit: true,
        ..PreCfg::GPT2
    };
    /// Falcon (and llama.cpp's "default"): punctuation runs, GPT-2 pattern, three-digit groups.
    pub const FALCON: PreCfg = PreCfg {
        punct_first: true,
        triple_digits: true,
        ..PreCfg::GPT2
    };
}

#[derive(Debug)]
pub struct Tokenizer {
    pub kind: Kind,
    pub pre: PreCfg,
    tokens: Vec<String>,
    vocab: HashMap<String, u32>,
    /// (left, right) → (rank, merged id)
    merges: HashMap<(u32, u32), (u32, u32)>,
    /// (content, id), longest first
    added: Vec<(String, u32)>,
    /// Byte trie over `added`: one pass per position, whatever the number of added tokens.
    added_trie: Vec<TrieNode>,
    /// 0 = ordinary, 1 = added, 2 = added and special; indexed by id
    added_flag: Vec<u8>,
    byte_ids: [Option<u32>; 256],
    b2c: [char; 256],
    rev: HashMap<char, u8>,
    ignore_merges: bool,
    add_prefix: bool,
    prog: Vec<Stage>,
    norms: Vec<Norm>,
    warns: Vec<String>,
    pub unk: Option<u32>,
    pub bos: Option<u32>,
    pub eos: Option<u32>,
}

// ------------------------------------------------------------------ helpers

/// GPT-2's reversible byte → printable character table, and its inverse.
fn byte_tables() -> ([char; 256], HashMap<char, u8>) {
    let mut t = ['\0'; 256];
    let mut rev = HashMap::with_capacity(256);
    let mut extra = 0u32;
    for (b, slot) in t.iter_mut().enumerate() {
        let printable =
            (33..=126).contains(&b) || (161..=172).contains(&b) || (174..=255).contains(&b);
        let c = if printable {
            b as u32
        } else {
            extra += 1;
            255 + extra
        };
        *slot = char::from_u32(c).unwrap_or('\u{fffd}');
        rev.insert(*slot, b as u8);
    }
    (t, rev)
}

fn parse_byte_token(t: &str) -> Option<u8> {
    let b = t.as_bytes();
    if b.len() != 6 || &b[..3] != b"<0x" || b[5] != b'>' {
        return None;
    }
    let hex = |c: u8| (c as char).to_digit(16);
    Some((hex(b[3])? * 16 + hex(b[4])?) as u8)
}

fn make_vocab(tokens: &[String]) -> HashMap<String, u32> {
    let mut v = HashMap::with_capacity(tokens.len());
    for (i, t) in tokens.iter().enumerate() {
        if !t.is_empty() {
            v.entry(t.clone()).or_insert(i as u32);
        }
    }
    v
}

fn resolve_merges(
    vocab: &HashMap<String, u32>,
    pairs: impl Iterator<Item = (String, String)>,
) -> Vec<(u32, u32, u32)> {
    pairs
        .filter_map(|(a, b)| {
            let (l, r) = (*vocab.get(&a)?, *vocab.get(&b)?);
            let m = *vocab.get(&format!("{a}{b}"))?;
            Some((l, r, m))
        })
        .collect()
}

fn merge_pair(v: &Value) -> Option<(String, String)> {
    match v {
        Value::String(s) => s
            .split_once(' ')
            .map(|(a, b)| (a.to_string(), b.to_string())),
        Value::Array(a) if a.len() == 2 => {
            Some((a[0].as_str()?.to_string(), a[1].as_str()?.to_string()))
        }
        _ => None,
    }
}

struct Parts {
    kind: Kind,
    pre: PreCfg,
    tokens: Vec<String>,
    vocab: HashMap<String, u32>,
    merge_ids: Vec<(u32, u32, u32)>,
    added: Vec<(u32, bool)>,
    unk: Option<u32>,
    bos: Option<u32>,
    eos: Option<u32>,
    add_prefix: bool,
    ignore_merges: bool,
    prog: Vec<Stage>,
    norms: Vec<Norm>,
    warns: Vec<String>,
}

fn assemble(p: Parts) -> Tokenizer {
    let (b2c, rev) = byte_tables();
    let mut merges = HashMap::with_capacity(p.merge_ids.len());
    for (rank, (l, r, m)) in p.merge_ids.into_iter().enumerate() {
        merges.entry((l, r)).or_insert((rank as u32, m));
    }
    let mut byte_ids = [None; 256];
    match p.kind {
        Kind::ByteLevel => {
            for (b, c) in b2c.iter().enumerate() {
                byte_ids[b] = p.vocab.get(&c.to_string()).copied();
            }
        }
        Kind::SentencePiece => {
            for (id, t) in p.tokens.iter().enumerate() {
                if let Some(b) = parse_byte_token(t) {
                    byte_ids[b as usize].get_or_insert(id as u32);
                }
            }
        }
    }
    let mut added_flag = vec![0u8; p.tokens.len()];
    let mut added: Vec<(String, u32)> = vec![];
    for (id, special) in p.added {
        let Some(content) = p.tokens.get(id as usize).filter(|c| !c.is_empty()) else {
            continue;
        };
        added_flag[id as usize] = 1 + special as u8;
        added.push((content.clone(), id));
    }
    added.sort_by(|a, b| b.0.len().cmp(&a.0.len()).then(a.1.cmp(&b.1)));
    let added_trie = build_trie(&added);
    Tokenizer {
        kind: p.kind,
        pre: p.pre,
        tokens: p.tokens,
        vocab: p.vocab,
        merges,
        added,
        added_trie,
        added_flag,
        byte_ids,
        b2c,
        rev,
        ignore_merges: p.ignore_merges,
        add_prefix: p.add_prefix,
        prog: p.prog,
        norms: p.norms,
        warns: p.warns,
        unk: p.unk,
        bos: p.bos,
        eos: p.eos,
    }
}

// ------------------------------------------------------- Unicode data and NFC

/// Unicode general categories (L, M, N, P, S) and canonical (NFC) normalisation without any
/// external crate. The range tables below were generated from the Unicode 15.1 character
/// database; characters assigned in later versions are classified as unassigned.
///
/// NFC covers every canonical decomposition of the BMP and beyond (≈1000 pairs), Hangul
/// algorithmically, and the combining-class reordering; it does NOT cover the CJK compatibility
/// ideographs (U+F900–FAFF, U+2F800–2FA1F), which NFC maps to unified ideographs, and it is not a
/// compatibility (NFKC/NFKD) normaliser — see [`nfkc_lite`].
